fn ensure_transfer_participant_eligible(
    participant: &TransferParticipant,
    label: &str,
) -> Result<(), String> {
    if participant.state != "alive" {
        return Err(format!("{label}的角色当前状态不能进行资产转移"));
    }
    if !participant.awakened {
        return Err(format!("{label}的角色尚未完成武魂觉醒"));
    }
    Ok(())
}

