fn insert_death_drops(
    connection: &Connection,
    player_id: i64,
    map_key: &str,
    battle_event_id: i64,
    created_at: i64,
) -> Result<Vec<GroundDropRecord>, String> {
    // 普通随身物品转成公共掉落；复活物品必须留在背包，否则死亡角色无法进入复活路径。
    let expires_at = created_at
        .checked_add(REVIVE_WINDOW_SECONDS)
        .ok_or_else(|| "死亡掉落过期时间溢出".to_string())?;
    let inventory = connection
        .prepare(
            r#"
            SELECT inv.item_key, inv.quantity
              FROM inventory inv
              JOIN item i ON i.item_key = inv.item_key
             WHERE inv.player_id = ?1 AND i.effect_kind <> 'revive'
             ORDER BY inv.item_key
            "#,
        )
        .map_err(|error| format!("准备死亡背包掉落查询失败：{error}"))?
        .query_map([player_id], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?))
        })
        .map_err(|error| format!("查询死亡背包掉落失败：{error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("解析死亡背包掉落失败：{error}"))?;

    let mut drops = Vec::new();
    for (item_key, quantity) in inventory {
        if quantity <= 0 {
            return Err("死亡背包中存在无效物品数量".to_string());
        }
        let mut remaining = quantity;
        let mut chunk = 1_i64;
        while remaining > 0 {
            let chunk_quantity = remaining.min(9_999);
            let source_event_id = format!("death:{battle_event_id}:{item_key}:{chunk}");
            validate_ground_drop_source("system", &source_event_id)?;
            connection
                .execute(
                    r#"
                    INSERT INTO ground_drop(
                        map_key, item_key, quantity, owner_identity_id, owner_subject_id,
                        source_kind, source_event_id, expires_at, created_at
                    ) VALUES(?1, ?2, ?3, NULL, NULL, 'system', ?4, ?5, ?6)
                    "#,
                    params![
                        map_key,
                        item_key,
                        chunk_quantity,
                        source_event_id,
                        expires_at,
                        created_at
                    ],
                )
                .map_err(|error| format!("写入死亡地面掉落失败：{error}"))?;
            let drop_id = connection.last_insert_rowid();
            drops.push(
                load_ground_drop_by_id(connection, drop_id)?
                    .ok_or_else(|| "写入死亡地面掉落后无法读取记录".to_string())?,
            );
            remaining -= chunk_quantity;
            chunk = chunk
                .checked_add(1)
                .ok_or_else(|| "死亡掉落堆编号溢出".to_string())?;
        }
    }

    connection
        .execute(
            r#"
            DELETE FROM inventory
             WHERE player_id = ?1
               AND item_key IN (
                   SELECT item_key FROM item WHERE effect_kind <> 'revive'
               )
            "#,
            [player_id],
        )
        .map_err(|error| format!("清空死亡普通背包失败：{error}"))?;
    Ok(drops)
}

fn load_death_drops_by_battle_event(
    connection: &Connection,
    battle_event_id: i64,
) -> Result<Vec<GroundDropRecord>, String> {
    let prefix = format!("death:{battle_event_id}:");
    connection
        .prepare(&format!(
            "{GROUND_DROP_SELECT} WHERE d.source_kind = 'system' AND d.source_event_id LIKE ?1 || '%' ORDER BY d.id"
        ))
        .map_err(|error| format!("准备死亡掉落重放查询失败：{error}"))?
        .query_map([prefix], ground_drop_record_from_row)
        .map_err(|error| format!("查询死亡掉落重放记录失败：{error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("解析死亡掉落重放记录失败：{error}"))
}

fn load_active_ground_drop(
    connection: &Connection,
    drop_id: i64,
    map_key: &str,
) -> Result<Option<GroundDropRecord>, String> {
    connection
        .query_row(
            &format!(
                "{GROUND_DROP_SELECT} WHERE d.id = ?1 AND d.map_key = ?2
                   AND NOT EXISTS(SELECT 1 FROM ground_drop_claim c WHERE c.drop_id = d.id)
                   AND NOT EXISTS(SELECT 1 FROM ground_drop_expiration e WHERE e.drop_id = d.id)"
            ),
            params![drop_id, map_key],
            ground_drop_record_from_row,
        )
        .optional()
        .map_err(|error| format!("读取当前地图地面掉落失败：{error}"))
}

fn query_active_ground_drops(
    connection: &Connection,
    map_key: &str,
    limit: i64,
    offset: i64,
) -> Result<Vec<GroundDropRecord>, String> {
    connection
        .prepare(&format!(
            "{GROUND_DROP_SELECT}
              WHERE d.map_key = ?1
                AND NOT EXISTS(SELECT 1 FROM ground_drop_claim c WHERE c.drop_id = d.id)
                AND NOT EXISTS(SELECT 1 FROM ground_drop_expiration e WHERE e.drop_id = d.id)
             ORDER BY d.id
             LIMIT ?2 OFFSET ?3"
        ))
        .map_err(|error| format!("准备地面掉落分页查询失败：{error}"))?
        .query_map(params![map_key, limit, offset], ground_drop_record_from_row)
        .map_err(|error| format!("查询地面掉落分页失败：{error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("解析地面掉落分页失败：{error}"))
}

fn active_ground_drop_count(connection: &Connection, map_key: &str) -> Result<usize, String> {
    let total = connection
        .query_row(
            r#"
            SELECT COUNT(*)
              FROM ground_drop d
             WHERE d.map_key = ?1
               AND NOT EXISTS(SELECT 1 FROM ground_drop_claim c WHERE c.drop_id = d.id)
               AND NOT EXISTS(SELECT 1 FROM ground_drop_expiration e WHERE e.drop_id = d.id)
            "#,
            [map_key],
            |row| row.get::<_, i64>(0),
        )
        .map_err(|error| format!("统计当前地图地面掉落失败：{error}"))?;
    usize::try_from(total).map_err(|_| "地面掉落数量超出分页范围".to_string())
}

fn expire_ground_drops_in_transaction(connection: &Connection) -> Result<usize, String> {
    let now = now_timestamp()?;
    connection
        .execute(
            r#"
            INSERT INTO ground_drop_expiration(drop_id, expires_at, expired_at)
            SELECT d.id, d.expires_at, ?1
              FROM ground_drop d
             WHERE d.expires_at IS NOT NULL
               AND d.expires_at <= ?1
               AND NOT EXISTS(SELECT 1 FROM ground_drop_claim c WHERE c.drop_id = d.id)
               AND NOT EXISTS(SELECT 1 FROM ground_drop_expiration e WHERE e.drop_id = d.id)
            "#,
            [now],
        )
        .map_err(|error| format!("记录过期地面掉落失败：{error}"))
}

