fn draw_weighted_wuhun(connection: &Connection) -> Result<(i64, AwakenedWuhun), String> {
    let total_weight = connection
        .query_row(
            r#"
            SELECT SUM(wuhun.weight)
              FROM wuhun
              JOIN content_revision_visible_member member
                ON member.member_kind = 'wuhun' AND member.member_key = wuhun.name
             WHERE member.revision_id = (
                       SELECT revision_id
                         FROM content_revision_activation
                        ORDER BY id DESC
                        LIMIT 1
                   )
            "#,
            [],
            |row| row.get::<_, Option<i64>>(0),
        )
        .map_err(|error| format!("读取武魂权重总和失败：{error}"))?
        .ok_or_else(|| "武魂目录为空，无法觉醒".to_string())?;
    if total_weight <= 0 {
        return Err("武魂权重总和必须大于 0".to_string());
    }
    let ticket = connection
        .query_row(
            "SELECT (random() & 9223372036854775807) % ?1",
            [total_weight],
            |row| row.get::<_, i64>(0),
        )
        .map_err(|error| format!("生成武魂权重签失败：{error}"))?;
    load_wuhun_at_weight_ticket(connection, ticket, total_weight)?
        .ok_or_else(|| "武魂权重目录不连续，无法完成觉醒".to_string())
}

fn load_wuhun_at_weight_ticket(
    connection: &Connection,
    ticket: i64,
    total_weight: i64,
) -> Result<Option<(i64, AwakenedWuhun)>, String> {
    if ticket < 0 || ticket >= total_weight {
        return Err("武魂权重签超出范围".to_string());
    }
    connection
        .query_row(
            r#"
            WITH weighted AS (
                SELECT wuhun.id, wuhun.name, wuhun.category, wuhun.form,
                       wuhun.description,
                       SUM(wuhun.weight) OVER (ORDER BY wuhun.id) AS cumulative_weight
                  FROM wuhun
                  JOIN content_revision_visible_member member
                    ON member.member_kind = 'wuhun' AND member.member_key = wuhun.name
                 WHERE member.revision_id = (
                           SELECT revision_id
                             FROM content_revision_activation
                            ORDER BY id DESC
                            LIMIT 1
                       )
            )
            SELECT id, name, category, form, description
              FROM weighted
             WHERE ?1 < cumulative_weight
             ORDER BY id
             LIMIT 1
            "#,
            [ticket],
            |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    AwakenedWuhun {
                        name: row.get(1)?,
                        category: row.get(2)?,
                        form: row.get(3)?,
                        description: row.get(4)?,
                    },
                ))
            },
        )
        .optional()
        .map_err(|error| format!("按权重选择武魂失败：{error}"))
}

