fn load_skill_effects(
    connection: &Connection,
    skill_key: &str,
) -> Result<Vec<SkillEffectRecord>, String> {
    connection
        .prepare(
            r#"
            SELECT effect_key, target_kind, operation, attribute_key, value_mode, value,
                   duration_rounds, description, trigger_kind, chance_percent,
                   stack_policy, parameters_json
              FROM effect_definition definition
              JOIN content_revision_visible_member member
                ON member.member_kind = 'effect' AND member.member_key = definition.effect_key
             WHERE member.revision_id = (
                       SELECT revision_id
                         FROM content_revision_activation
                        ORDER BY id DESC
                        LIMIT 1
                   )
               AND definition.skill_key = ?1
               AND definition.enabled = 1
             ORDER BY definition.effect_key
            "#,
        )
        .map_err(|error| format!("准备魂技效果查询失败：{error}"))?
        .query_map([skill_key], skill_effect_record_from_row)
        .map_err(|error| format!("查询魂技效果失败：{error}"))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("解析魂技效果失败：{error}"))
}

fn compatibility_effect_kind(
    operation: &str,
    attribute_key: &str,
    value_mode: &str,
    value: i64,
) -> String {
    if operation == "modify_stat"
        && attribute_key == "beast_attack"
        && value_mode == "percent_delta"
        && value < 0
    {
        "beast_attack_reduction".to_string()
    } else if operation == "deal_damage"
        && attribute_key == "beast_hp"
        && value_mode == "absolute"
        && value > 0
    {
        "poison_damage".to_string()
    } else if operation == "control"
        && attribute_key == "stunned"
        && value_mode == "absolute"
        && value == STUN_VALUE
    {
        "stun".to_string()
    } else if operation == "absorb_damage"
        && attribute_key == "beast_counterattack"
        && value_mode == "absolute"
        && value == SHIELD_VALUE
    {
        "shield".to_string()
    } else if operation == "restore"
        && attribute_key == "player_hp"
        && value_mode == "absolute"
        && value > 0
    {
        "heal".to_string()
    } else if operation == "control"
        && attribute_key == "skill_usage"
        && value_mode == "absolute"
        && value == FORBID_SKILL_VALUE
    {
        "skill_forbidden".to_string()
    } else if operation == "select_target"
        && attribute_key == "battle_target"
        && value_mode == "absolute"
        && value == TARGET_SELECTION_VALUE
    {
        "target_selection".to_string()
    } else {
        operation.to_string()
    }
}

fn compatibility_magnitude(
    operation: &str,
    attribute_key: &str,
    value_mode: &str,
    value: i64,
) -> i64 {
    if operation == "modify_stat"
        && attribute_key == "beast_attack"
        && value_mode == "percent_delta"
    {
        value.unsigned_abs() as i64
    } else {
        value
    }
}

fn player_skill_select_sql() -> &'static str {
    r#"
    SELECT ps.id,
           s.skill_key, s.name, s.skill_type, s.wuhun_category,
           s.ring_index, s.soul_power_cost, s.cooldown_rounds, s.base_damage,
           s.spirit_ratio_percent, s.strength_ratio_percent, s.description,
           ps.level, ps.proficiency, ps.equipped, ps.learned_at
      FROM player_skill_bound_projection ps
      JOIN skill s ON s.skill_key = ps.skill_key
    "#
}

fn soul_ring_select_sql() -> &'static str {
    r#"
    SELECT r.ring_key, r.name, r.soul_beast_id, sb.name, sb.age,
           s.skill_key, s.name, s.skill_type, s.wuhun_category,
           s.ring_index, s.soul_power_cost, s.cooldown_rounds, s.base_damage,
           s.spirit_ratio_percent, s.strength_ratio_percent, s.description,
           r.ring_index, r.age, r.color, r.description
      FROM soul_ring r
      JOIN soul_beast sb ON sb.id = r.soul_beast_id
      JOIN skill s ON s.skill_key = r.skill_key
    "#
}

fn player_soul_ring_select_sql() -> &'static str {
    r#"
    SELECT psr.id,
           r.ring_key, r.name, r.soul_beast_id, sb.name, sb.age,
           s.skill_key, s.name, s.skill_type, s.wuhun_category,
           s.ring_index, s.soul_power_cost, s.cooldown_rounds, s.base_damage,
           s.spirit_ratio_percent, s.strength_ratio_percent, s.description,
           r.ring_index, r.age, r.color, r.description,
           psr.ring_index, psr.obtained_at
      FROM player_soul_ring_current_projection psr
      JOIN soul_ring r ON r.ring_key = psr.ring_key
      JOIN soul_beast sb ON sb.id = r.soul_beast_id
      JOIN skill s ON s.skill_key = psr.skill_key
    "#
}

/// 历史回执必须读取原始附加记录，不能被当前投影中的剥离状态遮蔽。
fn player_soul_ring_history_select_sql() -> &'static str {
    r#"
    SELECT psr.id,
           r.ring_key, r.name, r.soul_beast_id, sb.name, sb.age,
           s.skill_key, s.name, s.skill_type, s.wuhun_category,
           s.ring_index, s.soul_power_cost, s.cooldown_rounds, s.base_damage,
           s.spirit_ratio_percent, s.strength_ratio_percent, s.description,
           r.ring_index, r.age, r.color, r.description,
           psr.ring_index, psr.obtained_at
      FROM player_soul_ring psr
      JOIN soul_ring r ON r.ring_key = psr.ring_key
      JOIN soul_beast sb ON sb.id = r.soul_beast_id
      JOIN skill s ON s.skill_key = psr.skill_key
    "#
}

fn soul_ring_drop_select_sql() -> &'static str {
    r#"
    SELECT drop_event.id, drop_event.battle_id, drop_event.battle_event_id,
           r.ring_key, r.name, r.soul_beast_id, sb.name, sb.age,
           s.skill_key, s.name, s.skill_type, s.wuhun_category,
           s.ring_index, s.soul_power_cost, s.cooldown_rounds, s.base_damage,
           s.spirit_ratio_percent, s.strength_ratio_percent, s.description,
           r.ring_index, r.age, r.color, r.description,
           drop_event.source_message_id, drop_event.status, drop_event.created_at
      FROM soul_ring_drop drop_event
      JOIN soul_ring r ON r.ring_key = drop_event.ring_key
      JOIN soul_beast sb ON sb.id = r.soul_beast_id
      JOIN skill s ON s.skill_key = r.skill_key
    "#
}

fn load_player_skill_by_name_or_key(
    connection: &Connection,
    player_id: i64,
    requested_name_or_key: &str,
) -> Result<PlayerSkillRecord, String> {
    let mut record = connection
        .query_row(
            &format!(
                "{} WHERE ps.player_id = ?1 AND (s.name = ?2 OR s.skill_key = ?2) LIMIT 1",
                player_skill_select_sql()
            ),
            params![player_id, requested_name_or_key],
            player_skill_record_from_row,
        )
        .optional()
        .map_err(|error| format!("读取玩家魂技失败：{error}"))
        .and_then(|record| {
            record.ok_or_else(|| format!("你尚未学习魂技“{requested_name_or_key}”"))
        })?;
    record.effects = load_skill_effects(connection, &record.skill.skill_key)?;
    Ok(record)
}

