fn load_soul_ring_detachment_by_message(
    connection: &Connection,
    player_id: i64,
    source_message_id: &str,
) -> Result<Option<SoulRingDetachmentReceipt>, String> {
    let player_soul_ring_id = connection
        .query_row(
            "SELECT player_soul_ring_id FROM player_soul_ring_detachment WHERE player_id = ?1 AND source_message_id = ?2",
            params![player_id, source_message_id],
            |row| row.get::<_, i64>(0),
        )
        .optional()
        .map_err(|error| format!("读取魂环剥离消息幂等记录失败：{error}"))?;
    let Some(player_soul_ring_id) = player_soul_ring_id else {
        return Ok(None);
    };
    let ring = load_player_soul_ring_history_by_id(connection, player_soul_ring_id)?
        .ok_or_else(|| "魂环剥离记录缺少原始魂环，已拒绝重放".to_string())?;
    Ok(Some(SoulRingDetachmentReceipt {
        skill: ring.ring.skill.clone(),
        ring,
        replayed: true,
    }))
}

#[allow(clippy::too_many_arguments)]
fn insert_soul_ring_drop(
    connection: &Connection,
    battle_id: i64,
    battle_event_id: i64,
    player_id: i64,
    soul_beast_id: i64,
    source_message_id: &str,
    operation_log_id: i64,
    created_at: i64,
) -> Result<Option<SoulRingDropRecord>, String> {
    let inserted = connection
        .execute(
            r#"
            INSERT INTO soul_ring_drop(
                battle_id, battle_event_id, player_id, ring_key,
                source_message_id, operation_log_id, status, created_at
            )
            SELECT ?1, ?2, ?3, ring.ring_key, ?4, ?5, 'pending', ?6
              FROM soul_ring ring
              JOIN content_revision_visible_member member
                ON member.member_kind = 'ring' AND member.member_key = ring.ring_key
             WHERE member.revision_id = (
                       SELECT revision_id
                         FROM content_revision_activation
                        ORDER BY id DESC
                        LIMIT 1
                   )
               AND ring.soul_beast_id = ?7
               AND ring.enabled = 1
            "#,
            params![
                battle_id,
                battle_event_id,
                player_id,
                source_message_id,
                operation_log_id,
                created_at,
                soul_beast_id
            ],
        )
        .map_err(|error| format!("保存战斗魂环掉落失败：{error}"))?;
    if inserted == 0 {
        return Ok(None);
    }
    load_soul_ring_drop_by_id(connection, connection.last_insert_rowid())
}

