#[allow(dead_code)]
fn wuhun_combat_modifier(category: &str) -> WuhunCombatModifier {
    match category {
        "强攻系" => WuhunCombatModifier {
            attack_percent: 120,
            defense_percent: 80,
        },
        "控制系" => WuhunCombatModifier {
            attack_percent: 90,
            defense_percent: 100,
        },
        "敏攻系" => WuhunCombatModifier {
            attack_percent: 100,
            defense_percent: 90,
        },
        "辅助系" => WuhunCombatModifier {
            attack_percent: 70,
            defense_percent: 110,
        },
        "防御系" => WuhunCombatModifier {
            attack_percent: 80,
            defense_percent: 130,
        },
        "食物系" => WuhunCombatModifier {
            attack_percent: 60,
            defense_percent: 100,
        },
        _ => WuhunCombatModifier {
            attack_percent: 100,
            defense_percent: 100,
        },
    }
}

fn load_wuhun_combat_modifier(
    connection: &Connection,
    wuhun_id: i64,
    category: &str,
) -> Result<WuhunCombatModifier, String> {
    let template = connection
        .query_row(
            r#"
            SELECT template.attack_percent, template.defense_percent, template.parameters_json
              FROM wuhun_stat_template template
              JOIN wuhun ON wuhun.id = template.wuhun_id
              JOIN content_revision_visible_member member
                ON member.member_kind = 'wuhun' AND member.member_key = wuhun.name
             WHERE template.wuhun_id = ?1
               AND member.revision_id = (
                       SELECT revision_id
                         FROM content_revision_activation
                        ORDER BY id DESC
                        LIMIT 1
                   )
            "#,
            [wuhun_id],
            |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, i64>(1)?,
                    row.get::<_, String>(2)?,
                ))
            },
        )
        .optional()
        .map_err(|error| format!("读取武魂属性模板失败：{error}"))?
        .ok_or_else(|| format!("武魂 {category} 缺少版本化属性模板"))?;
    let source = serde_json::from_str::<serde_json::Value>(&template.2)
        .ok()
        .and_then(|value| {
            value
                .get("source")
                .and_then(|source| source.as_str())
                .map(str::to_string)
        });
    if source.as_deref() == Some("category-v1") {
        Ok(wuhun_combat_modifier(category))
    } else {
        Ok(WuhunCombatModifier {
            attack_percent: template.0,
            defense_percent: template.1,
        })
    }
}

fn active_wuhun_modifier(enabled: bool, modifier: WuhunCombatModifier) -> WuhunCombatModifier {
    if enabled {
        modifier
    } else {
        WuhunCombatModifier {
            attack_percent: 100,
            defense_percent: 100,
        }
    }
}

fn scale_combat_value(value: i64, percent: i64, label: &str) -> Result<i64, String> {
    if value < 0 || percent <= 0 {
        return Err(format!("{label}参数无效"));
    }
    i64::try_from(
        i128::from(value)
            .checked_mul(i128::from(percent))
            .ok_or_else(|| format!("{label}计算溢出"))?
            / 100,
    )
    .map_err(|_| format!("{label}超出整数范围"))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum EffectStackPolicy {
    Strongest,
    Add,
    Refresh,
    Replace,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SupportedSkillEffect {
    BeastAttackReduction {
        reduction: i64,
        stack_policy: EffectStackPolicy,
    },
    PoisonDamage {
        damage: i64,
        stack_policy: EffectStackPolicy,
    },
    BeastStun {
        stack_policy: EffectStackPolicy,
    },
    BeastShield {
        stack_policy: EffectStackPolicy,
    },
    PlayerHeal {
        amount: i64,
        stack_policy: EffectStackPolicy,
    },
    CurrentBattleBeastTarget {
        stack_policy: EffectStackPolicy,
    },
    PlayerSkillForbidden {
        stack_policy: EffectStackPolicy,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PoisonDamageAccumulator {
    stack_policy: EffectStackPolicy,
    additive_damage: i64,
    strongest_damage: i64,
    latest_damage: i64,
}

fn effect_stack_policy(value: &str) -> Result<EffectStackPolicy, String> {
    match value {
        "strongest" => Ok(EffectStackPolicy::Strongest),
        "add" => Ok(EffectStackPolicy::Add),
        "refresh" => Ok(EffectStackPolicy::Refresh),
        "replace" => Ok(EffectStackPolicy::Replace),
        _ => Err(format!("当前魂技效果解释器不支持叠加策略 {value}")),
    }
}

#[allow(clippy::too_many_arguments)]
fn parse_supported_skill_effect(
    trigger_kind: &str,
    target_kind: &str,
    operation: &str,
    attribute_key: &str,
    value_mode: &str,
    value: i64,
    chance_percent: i64,
    stack_policy: &str,
    parameters_json: &str,
) -> Result<SupportedSkillEffect, String> {
    let parameters = serde_json::from_str::<BTreeMap<String, serde_json::Value>>(parameters_json)
        .map_err(|error| format!("魂技效果参数不是有效 JSON 对象：{error}"))?;
    let stack_policy = effect_stack_policy(stack_policy)?;
    if trigger_kind == "on_release"
        && matches!(target_kind, "enemy" | "beast")
        && operation == "modify_stat"
        && attribute_key == "beast_attack"
        && value_mode == "percent_delta"
        && (-90..=-1).contains(&value)
        && chance_percent == 100
    {
        if !parameters.is_empty() {
            return Err("当前魂技减攻效果不支持非空 parameters".to_string());
        }
        return Ok(SupportedSkillEffect::BeastAttackReduction {
            reduction: value
                .checked_neg()
                .ok_or_else(|| "魂技效果数值超出范围".to_string())?,
            stack_policy,
        });
    }
    if trigger_kind == "on_release"
        && target_kind == "beast"
        && operation == "deal_damage"
        && attribute_key == "beast_hp"
        && value_mode == "absolute"
        && (1..=MAX_POISON_TICK_DAMAGE).contains(&value)
        && chance_percent == 100
    {
        if !is_poison_v1_parameters(&parameters) {
            return Err("poison-v1 参数必须固定声明规则版本、结算时机和间隔".to_string());
        }
        return Ok(SupportedSkillEffect::PoisonDamage {
            damage: value,
            stack_policy,
        });
    }
    if trigger_kind == "on_release"
        && target_kind == "beast"
        && operation == "control"
        && attribute_key == "stunned"
        && value_mode == "absolute"
        && value == STUN_VALUE
        && chance_percent == 100
    {
        if !is_stun_v1_parameters(&parameters) {
            return Err("stun-v1 参数必须固定声明规则版本、结算时机和反击行为".to_string());
        }
        if stack_policy != EffectStackPolicy::Refresh {
            return Err("stun-v1 只支持 refresh 叠加策略".to_string());
        }
        return Ok(SupportedSkillEffect::BeastStun { stack_policy });
    }
    if trigger_kind == "on_release"
        && target_kind == "self"
        && operation == "absorb_damage"
        && attribute_key == "beast_counterattack"
        && value_mode == "absolute"
        && value == SHIELD_VALUE
        && chance_percent == 100
    {
        if !is_shield_v1_parameters(&parameters) {
            return Err("shield-v1 参数必须固定声明规则版本、结算时机和反击行为".to_string());
        }
        if stack_policy != EffectStackPolicy::Refresh {
            return Err("shield-v1 只支持 refresh 叠加策略".to_string());
        }
        return Ok(SupportedSkillEffect::BeastShield { stack_policy });
    }
    if trigger_kind == "on_release"
        && target_kind == "self"
        && operation == "restore"
        && attribute_key == "player_hp"
        && value_mode == "absolute"
        && (1..=MAX_HEAL_AMOUNT).contains(&value)
        && chance_percent == 100
    {
        if !is_heal_v1_parameters(&parameters) {
            return Err("heal-v1 参数必须固定声明规则版本、结算时机和溢出行为".to_string());
        }
        if stack_policy != EffectStackPolicy::Add {
            return Err("heal-v1 只支持 add 叠加策略".to_string());
        }
        return Ok(SupportedSkillEffect::PlayerHeal {
            amount: value,
            stack_policy,
        });
    }
    if trigger_kind == "on_release"
        && target_kind == "self"
        && operation == "control"
        && attribute_key == "skill_usage"
        && value_mode == "absolute"
        && value == FORBID_SKILL_VALUE
        && chance_percent == 100
    {
        if !is_forbid_skill_v1_parameters(&parameters) {
            return Err("forbid-skill-v1 参数必须固定声明规则版本、结算时机和阻断动作".to_string());
        }
        if stack_policy != EffectStackPolicy::Refresh {
            return Err("forbid-skill-v1 只支持 refresh 叠加策略".to_string());
        }
        return Ok(SupportedSkillEffect::PlayerSkillForbidden { stack_policy });
    }
    if trigger_kind == "on_release"
        && target_kind == "beast"
        && operation == "select_target"
        && attribute_key == "battle_target"
        && value_mode == "absolute"
        && value == TARGET_SELECTION_VALUE
        && chance_percent == 100
    {
        if !is_target_v1_parameters(&parameters) {
            return Err("target-v1 参数必须固定声明当前战斗魂兽选择器".to_string());
        }
        if stack_policy != EffectStackPolicy::Replace {
            return Err("target-v1 只支持 replace 叠加策略".to_string());
        }
        return Ok(SupportedSkillEffect::CurrentBattleBeastTarget { stack_policy });
    }
    Err(format!(
        "当前魂技效果解释器不支持 {trigger_kind}/{target_kind}/{operation}/{attribute_key}/{value_mode}/{value}/{chance_percent}"
    ))
}

fn beast_attack_after_skill_effects(
    beast_attack: i64,
    active_effects: &[BattleSkillEffectRecord],
    pending_effects: &[SkillEffectRecord],
) -> Result<i64, String> {
    let mut strongest = 0_i64;
    let mut additive = 0_i64;
    let mut replacement = None;
    for effect in active_effects {
        apply_beast_attack_effect(
            parse_supported_skill_effect(
                &effect.trigger_kind,
                &effect.target_kind,
                &effect.operation,
                &effect.attribute_key,
                &effect.value_mode,
                effect.value,
                effect.chance_percent,
                &effect.stack_policy,
                &effect.parameters_json,
            )?,
            &mut strongest,
            &mut additive,
            &mut replacement,
        )?;
    }
    for effect in pending_effects {
        apply_beast_attack_effect(
            parse_supported_skill_effect(
                &effect.trigger_kind,
                &effect.target_kind,
                &effect.operation,
                &effect.attribute_key,
                &effect.value_mode,
                effect.value,
                effect.chance_percent,
                &effect.stack_policy,
                &effect.parameters_json,
            )?,
            &mut strongest,
            &mut additive,
            &mut replacement,
        )?;
    }
    let base_reduction = strongest.max(replacement.unwrap_or(0));
    let reduction = base_reduction
        .checked_add(additive)
        .ok_or_else(|| "魂技减攻效果叠加溢出".to_string())?
        .min(90);
    if reduction == 0 {
        return Ok(beast_attack);
    }
    let remaining_percent = 100_i64
        .checked_sub(reduction)
        .ok_or_else(|| "魂技减攻效果超出范围".to_string())?;
    scale_combat_value(beast_attack, remaining_percent, "魂技减攻效果").map(|scaled| scaled.max(1))
}

fn apply_beast_attack_effect(
    effect: SupportedSkillEffect,
    strongest: &mut i64,
    additive: &mut i64,
    replacement: &mut Option<i64>,
) -> Result<(), String> {
    let SupportedSkillEffect::BeastAttackReduction {
        reduction,
        stack_policy,
    } = effect
    else {
        return Ok(());
    };
    match stack_policy {
        EffectStackPolicy::Strongest | EffectStackPolicy::Refresh => {
            *strongest = (*strongest).max(reduction);
        }
        EffectStackPolicy::Add => {
            *additive = additive
                .checked_add(reduction)
                .ok_or_else(|| "魂技效果叠加数值溢出".to_string())?;
        }
        EffectStackPolicy::Replace => *replacement = Some(reduction),
    }
    Ok(())
}

/// 判断当前玩家动作是否使魂兽跳过本次反击；所有效果仍需完整解析以保持 fail-closed。
fn beast_is_stunned_after_skill_effects(
    active_effects: &[BattleSkillEffectRecord],
    pending_effects: &[SkillEffectRecord],
) -> Result<bool, String> {
    let mut stunned = false;
    for effect in active_effects {
        if matches!(
            parse_supported_skill_effect(
                &effect.trigger_kind,
                &effect.target_kind,
                &effect.operation,
                &effect.attribute_key,
                &effect.value_mode,
                effect.value,
                effect.chance_percent,
                &effect.stack_policy,
                &effect.parameters_json,
            )?,
            SupportedSkillEffect::BeastStun { .. }
        ) {
            stunned = true;
        }
    }
    for effect in pending_effects {
        if matches!(
            parse_supported_skill_effect(
                &effect.trigger_kind,
                &effect.target_kind,
                &effect.operation,
                &effect.attribute_key,
                &effect.value_mode,
                effect.value,
                effect.chance_percent,
                &effect.stack_policy,
                &effect.parameters_json,
            )?,
            SupportedSkillEffect::BeastStun { .. }
        ) {
            stunned = true;
        }
    }
    Ok(stunned)
}

