    fn register_awakened_pair(store: &Store) {
        store
            .register_player(&identity(), "转移发送方", "男")
            .expect("应创建资产转移发送方");
        store
            .awaken_wuhun(&identity())
            .expect("发送方应完成武魂觉醒");
        store
            .register_player(&recipient_identity(), "转移接收方", "女")
            .expect("应创建资产转移接收方");
        store
            .awaken_wuhun(&recipient_identity())
            .expect("接收方应完成武魂觉醒");
    }

    fn absorb_test_soul_ring(
        store: &Store,
        key: &IdentityKey<'_>,
        message_prefix: &str,
    ) -> SoulRingAbsorbReceipt {
        absorb_test_soul_ring_from_beast(store, key, "史莱姆", message_prefix)
    }

    fn absorb_test_soul_ring_from_beast(
        store: &Store,
        key: &IdentityKey<'_>,
        soul_beast_name_or_key: &str,
        message_prefix: &str,
    ) -> SoulRingAbsorbReceipt {
        let player_id = player_id_for(store, key);
        store
            .open()
            .expect("应打开魂环测试数据库")
            .execute(
                "UPDATE player SET level = 10, hp = 1000, max_hp = 1000, strength = 1000, perception = 0, luck = 0, endurance = 100, soul_power = 100, max_soul_power = 100, updated_at = 1 WHERE id = ?1",
                [player_id],
            )
            .expect("应设置魂环测试属性");
        let map_message = format!("{message_prefix}-map");
        store
            .teleport_with_operation(key, Some("落日森林"), &map_operation("传送", &map_message))
            .expect("应进入魂环测试地图");
        let challenge_message = format!("{message_prefix}-challenge");
        store
            .challenge_soul_beast_with_operation(
                key,
                soul_beast_name_or_key,
                &transfer_operation("挑战", &challenge_message),
            )
            .expect("应挑战掉落测试魂环的魂兽");
        let win_message = format!("{message_prefix}-win");
        let victory = store
            .attack_battle_with_operation(key, &transfer_operation("攻击", &win_message))
            .expect("应击败掉落测试魂环的魂兽");
        assert_eq!(victory.event.status_after, "won");
        let absorb_message = format!("{message_prefix}-absorb");
        store
            .absorb_soul_ring_with_operation(
                key,
                soul_beast_name_or_key,
                &transfer_operation("吸收魂环", &absorb_message),
            )
            .expect("应吸收测试魂环")
    }

    fn player_id_for(store: &Store, key: &IdentityKey<'_>) -> i64 {
        store
            .open()
            .expect("应打开测试数据库")
            .query_row(
                r#"
                SELECT p.id FROM identity i
                JOIN player p ON p.identity_id = i.id
                WHERE i.protocol = ?1 AND i.account_id = ?2 AND i.namespace = ?3
                  AND i.subject_kind = ?4 AND i.subject_id = ?5
                "#,
                params![
                    key.protocol.as_str(),
                    key.account_id,
                    key.namespace,
                    key.subject_kind,
                    key.subject_id
                ],
                |row| row.get(0),
            )
            .expect("应读取测试角色 ID")
    }

    fn set_skill_progress_for_test(store: &Store, player_id: i64, level: i64, proficiency: i64) {
        let connection = store.open().expect("应打开魂技等级测试数据库");
        connection
            .execute_batch("DROP TRIGGER player_skill_progress_guard;")
            .expect("应暂时移除成长更新门控");
        connection
            .execute(
                "UPDATE player_skill SET level = ?1, proficiency = ?2 WHERE player_id = ?3 AND skill_key = 'entangle'",
                params![level, proficiency, player_id],
            )
            .expect("应设置测试魂技成长状态");
        connection
            .execute_batch(
                r#"
                CREATE TRIGGER player_skill_progress_guard
                BEFORE UPDATE OF level, proficiency ON player_skill
                WHEN NEW.level <> OLD.level OR NEW.proficiency <> OLD.proficiency
                BEGIN
                    SELECT CASE WHEN NOT EXISTS(
                        SELECT 1
                          FROM skill_progress_event progress
                         WHERE progress.player_id = OLD.player_id
                           AND progress.player_skill_id = OLD.id
                           AND progress.skill_key = OLD.skill_key
                           AND progress.level_before = OLD.level
                           AND progress.level_after = NEW.level
                           AND progress.proficiency_before = OLD.proficiency
                           AND progress.proficiency_after = NEW.proficiency
                           AND progress.id = (
                               SELECT MAX(latest.id)
                                 FROM skill_progress_event latest
                                WHERE latest.player_skill_id = OLD.id
                           )
                    ) THEN RAISE(ABORT, 'player skill progress must follow an event') END;
                END;
                "#,
            )
            .expect("应恢复成长更新门控");
    }

    fn transfer_operation<'a>(command: &'a str, message_id: &'a str) -> OperationLogInput<'a> {
        OperationLogInput {
            command,
            outcome: "ok",
            source_message_id: message_id,
            details_json: r#"{"context":"private","has_args":true}"#,
        }
    }

    fn seed_wallet(store: &Store, key: &IdentityKey<'_>, balance: i64) {
        let player_id = player_id_for(store, key);
        store
            .open()
            .expect("应打开测试数据库")
            .execute(
                r#"
                INSERT INTO wallet(player_id, currency_code, balance, created_at, updated_at)
                VALUES(?1, 'gold_soul_coin', ?2, 0, 0)
                ON CONFLICT(player_id, currency_code) DO UPDATE SET
                    balance = excluded.balance,
                    updated_at = excluded.updated_at
                "#,
                params![player_id, balance],
            )
            .expect("应设置测试钱包余额");
    }

    fn seed_inventory(store: &Store, key: &IdentityKey<'_>, item_key: &str, quantity: i64) {
        let player_id = player_id_for(store, key);
        store
            .open()
            .expect("应打开测试数据库")
            .execute(
                r#"
                INSERT INTO inventory(player_id, item_key, quantity, updated_at)
                VALUES(?1, ?2, ?3, 0)
                ON CONFLICT(player_id, item_key) DO UPDATE SET
                    quantity = excluded.quantity,
                    updated_at = excluded.updated_at
                "#,
                params![player_id, item_key, quantity],
            )
            .expect("应设置测试背包数量");
    }

    fn inventory_for(store: &Store, key: &IdentityKey<'_>, item_key: &str) -> i64 {
        inventory_quantity(
            &store.open().expect("应打开测试数据库"),
            player_id_for(store, key),
            item_key,
        )
        .expect("应读取测试背包数量")
    }

    fn assert_v9_damage_fails_closed(mutation: &str) {
        let directory = tempdir().expect("应创建 v9 损坏测试目录");
        let store =
            Store::initialize(directory.path(), &DatabaseConfig::default()).expect("v9 迁移应成功");
        let connection = store.open().expect("应打开 v9 损坏测试数据库");
        connection
            .execute_batch(mutation)
            .expect("应能构造 v9 schema 损坏");
        drop(connection);
        drop(store);
        let error = Store::initialize(directory.path(), &DatabaseConfig::default())
            .expect_err("记录 v9 后损坏 schema 必须拒绝启动");
        assert!(
            error.contains("v9"),
            "v9 损坏未由对应校验拒绝：{mutation}；实际错误：{error}"
        );
    }

