    #[test]
    fn v23_published_effect_definition_drives_the_same_interpreter() {
        let (directory, store) = test_store();
        register_awakened_pair(&store);
        let package = ContentPackage {
            package_key: "test-effects".to_string(),
            revision: 1,
            author: "test".to_string(),
            minimum_runtime: String::new(),
            wuhun: Vec::new(),
            skills: Vec::new(),
            effects: vec![EffectPackageEntry {
                effect_key: "entangle-heavy".to_string(),
                skill_key: "entangle".to_string(),
                trigger_kind: "on_release".to_string(),
                target_kind: "enemy".to_string(),
                operation: "modify_stat".to_string(),
                attribute_key: "beast_attack".to_string(),
                value_mode: "percent_delta".to_string(),
                value: -50,
                duration_rounds: 2,
                chance_percent: 100,
                stack_policy: "strongest".to_string(),
                parameters: Default::default(),
                description: "test content effect".to_string(),
                enabled: true,
            }],
            soul_beasts: Vec::new(),
            soul_rings: Vec::new(),
            transitions: Vec::new(),
        };
        let loaded = LoadedContentPackage {
            content_hash: content_hash(&package).expect("content hash"),
            package,
            source_format: "json".to_string(),
        };
        store
            .stage_content_package(&loaded)
            .expect("content package should stage");
        let validation = store
            .validate_content_draft("test-effects", 1)
            .expect("content package should validate");
        assert!(validation.errors.is_empty(), "{validation:?}");
        let published = store
            .publish_content_draft("test-effects", 1)
            .expect("content package should publish");
        assert!(!published.replayed);
        // 魂技只能由真实吸收魂环产生，测试也必须走与玩家一致的绑定流程。
        let _ring = absorb_test_soul_ring(&store, &identity(), "v23-custom-ring");
        let player_id = player_id_for(&store, &identity());
        let connection = store.open().expect("应打开 v23 自定义效果数据库");
        connection
            .execute(
                "UPDATE player SET level = 3, hp = 1000, max_hp = 1000, soul_power = 1000, max_soul_power = 1000, strength = 1, endurance = 0, perception = 0, luck = 0, updated_at = 1 WHERE id = ?1",
                [player_id],
            )
            .expect("应设置自定义效果测试属性");
        drop(connection);
        store
            .challenge_soul_beast_with_operation(
                &identity(),
                "哥布林",
                &transfer_operation("挑战", "v23-custom-start"),
            )
            .expect("应创建自定义效果测试战斗");
        let release = store
            .use_skill_battle_with_operation(
                &identity(),
                "缠绕",
                &transfer_operation("释放技能", "v23-custom-use"),
            )
            .expect("自定义效果应复用通用解释器");
        assert_eq!(
            release.skill.as_ref().expect("应有魂技回执").effects.len(),
            2
        );
        assert!(
            release
                .skill
                .as_ref()
                .unwrap()
                .effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-heavy" && effect.value == -50)
        );
        assert_eq!(release.battle.active_effects.len(), 2);
        let connection = store.open().expect("应读取 v23 自定义快照");
        let snapshot = connection
            .query_row(
                "SELECT operation, attribute_key, value_mode, value, rule_version FROM battle_effect_snapshot WHERE effect_key = 'entangle-heavy'",
                [],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, String>(2)?,
                        row.get::<_, i64>(3)?,
                        row.get::<_, String>(4)?,
                    ))
                },
            )
            .expect("应读取自定义效果释放快照");
        assert_eq!(
            snapshot,
            (
                "modify_stat".to_string(),
                "beast_attack".to_string(),
                "percent_delta".to_string(),
                -50,
                "effect-v2".to_string()
            )
        );
        drop(connection);
        drop(store);
        let restored = Store::initialize(directory.path(), &DatabaseConfig::default())
            .expect("自定义效果数据库应可热重载");
        let active = restored
            .active_battle(&identity())
            .expect("应读取重载后的自定义战斗")
            .expect("自定义效果战斗应仍进行中");
        assert!(
            active
                .active_effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-heavy")
        );
    }

    #[test]
    fn target_v1_uses_the_current_battle_beast_without_extra_state() {
        let (_directory, store) = test_store();
        register_awakened_pair(&store);
        let target = target_effect_package("target-v1-test", "entangle-target-test", "entangle");
        store
            .stage_content_package(&target)
            .expect("目标选择内容包应暂存");
        let validation = store
            .validate_content_draft("target-v1-test", 1)
            .expect("目标选择内容包应校验");
        assert!(validation.errors.is_empty(), "{validation:?}");
        store
            .publish_content_draft("target-v1-test", 1)
            .expect("目标选择内容包应发布");
        absorb_test_soul_ring(&store, &identity(), "target-v1-source");

        let player_id = player_id_for(&store, &identity());
        let connection = store.open().expect("应打开目标选择战斗数据库");
        connection
            .execute(
                "UPDATE player SET level = 10, hp = 1000, max_hp = 1000, soul_power = 1000, max_soul_power = 1000, strength = 1, endurance = 1000, perception = 0, luck = 0, updated_at = 1 WHERE id = ?1",
                [player_id],
            )
            .expect("应设置目标选择战斗属性");
        drop(connection);
        store
            .challenge_soul_beast_with_operation(
                &identity(),
                "哥布林",
                &transfer_operation("挑战", "target-v1-challenge"),
            )
            .expect("应创建目标选择测试战斗");
        let first = store
            .use_skill_battle_with_operation(
                &identity(),
                "缠绕",
                &transfer_operation("释放技能", "target-v1-use"),
            )
            .expect("目标选择应直接使用当前战斗魂兽");
        let first_skill = first.skill.as_ref().expect("应有目标选择魂技回执");
        assert!(
            first_skill
                .effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-target-test")
        );
        assert!(
            first
                .expired_effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-target-test")
        );
        assert_eq!(first.event.sequence, 1);
        assert_eq!(first.event.beast_hp_before, first.battle.beast.max_hp);
    }

    #[test]
    fn forbid_skill_v1_blocks_release_before_mutation_and_expires() {
        let (_directory, store) = test_store();
        register_awakened_pair(&store);
        let forbid = forbid_skill_effect_package(
            "forbid-skill-v1-test",
            "entangle-forbid-skill-test",
            "entangle",
            2,
        );
        store
            .stage_content_package(&forbid)
            .expect("禁技内容包应暂存");
        let validation = store
            .validate_content_draft("forbid-skill-v1-test", 1)
            .expect("禁技内容包应校验");
        assert!(validation.errors.is_empty(), "{validation:?}");
        store
            .publish_content_draft("forbid-skill-v1-test", 1)
            .expect("禁技内容包应发布");
        absorb_test_soul_ring(&store, &identity(), "forbid-skill-v1-source");

        let player_id = player_id_for(&store, &identity());
        let connection = store.open().expect("应打开禁技战斗数据库");
        connection
            .execute(
                "UPDATE player SET level = 10, hp = 1000, max_hp = 1000, soul_power = 1000, max_soul_power = 1000, strength = 1, endurance = 1000, perception = 0, luck = 0, updated_at = 1 WHERE id = ?1",
                [player_id],
            )
            .expect("应设置禁技战斗属性");
        drop(connection);
        store
            .challenge_soul_beast_with_operation(
                &identity(),
                "哥布林",
                &transfer_operation("挑战", "forbid-skill-v1-challenge"),
            )
            .expect("应创建禁技测试战斗");

        let first = store
            .use_skill_battle_with_operation(
                &identity(),
                "缠绕",
                &transfer_operation("释放技能", "forbid-skill-v1-first"),
            )
            .expect("首次魂技应正常释放并施加禁技");
        assert_eq!(first.event.sequence, 1);
        assert!(
            first
                .skill
                .as_ref()
                .expect("首次应有魂技回执")
                .effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-forbid-skill-test")
        );
        let power_after_first = first
            .skill
            .as_ref()
            .expect("首次应保存魂力回执")
            .soul_power_after;

        let blocked = store
            .use_skill_battle_with_operation(
                &identity(),
                "缠绕",
                &transfer_operation("释放技能", "forbid-skill-v1-blocked"),
            )
            .expect_err("禁技期间释放魂技应失败");
        assert!(blocked.contains("禁技"));
        let connection = store.open().expect("应读取禁技阻断后的状态");
        let (action_count, soul_power, blocked_events) = connection
            .query_row(
                "SELECT battle.action_count, player.soul_power, (SELECT COUNT(*) FROM battle_event WHERE source_message_id = ?1) FROM battle JOIN player ON player.id = battle.player_id WHERE battle.player_id = ?2 AND battle.status = 'active'",
                params!["forbid-skill-v1-blocked", player_id],
                |row| {
                    Ok((
                        row.get::<_, i64>(0)?,
                        row.get::<_, i64>(1)?,
                        row.get::<_, i64>(2)?,
                    ))
                },
            )
            .expect("应读取禁技阻断状态");
        assert_eq!(action_count, 1);
        assert_eq!(soul_power, power_after_first);
        assert_eq!(blocked_events, 0);

        let second = store
            .attack_battle_with_operation(
                &identity(),
                &transfer_operation("攻击", "forbid-skill-v1-wait-1"),
            )
            .expect("普通攻击不应被禁技阻断");
        assert_eq!(second.event.sequence, 2);
        assert!(
            second
                .expired_effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-forbid-skill-test")
        );
        let third = store
            .attack_battle_with_operation(
                &identity(),
                &transfer_operation("攻击", "forbid-skill-v1-wait-2"),
            )
            .expect("禁技到期后仍应允许普通攻击");
        assert_eq!(third.event.sequence, 3);
        assert!(
            !third
                .battle
                .active_effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-forbid-skill-test")
        );

        let fourth = store
            .use_skill_battle_with_operation(
                &identity(),
                "缠绕",
                &transfer_operation("释放技能", "forbid-skill-v1-after-expiry"),
            )
            .expect("禁技到期且冷却结束后应允许再次释放魂技");
        assert_eq!(fourth.event.sequence, 4);
    }

    #[test]
    fn stun_v1_skips_counterattack_and_survives_content_rollback() {
        let (directory, store) = test_store();
        register_awakened_pair(&store);
        let baseline = store
            .active_content_revision()
            .expect("应读取眩晕测试的 baseline revision");
        let stun = stun_effect_package("stun-v1-test", "entangle-stun-test", "entangle", 2);
        store
            .stage_content_package(&stun)
            .expect("眩晕内容包应暂存");
        let validation = store
            .validate_content_draft("stun-v1-test", 1)
            .expect("眩晕内容包应校验");
        assert!(validation.errors.is_empty(), "{validation:?}");
        store
            .publish_content_draft("stun-v1-test", 1)
            .expect("眩晕内容包应发布");
        absorb_test_soul_ring(&store, &identity(), "stun-v1-source");

        let player_id = player_id_for(&store, &identity());
        let connection = store.open().expect("应打开眩晕战斗数据库");
        connection
            .execute(
                "UPDATE player SET level = 10, hp = 1000, max_hp = 1000, soul_power = 1000, max_soul_power = 1000, strength = 1, endurance = 1000, perception = 0, luck = 0, updated_at = 1 WHERE id = ?1",
                [player_id],
            )
            .expect("应设置眩晕战斗属性");
        drop(connection);
        store
            .challenge_soul_beast_with_operation(
                &identity(),
                "哥布林",
                &transfer_operation("挑战", "stun-v1-challenge"),
            )
            .expect("应创建眩晕测试战斗");

        let first = store
            .use_skill_battle_with_operation(
                &identity(),
                "缠绕",
                &transfer_operation("释放技能", "stun-v1-first"),
            )
            .expect("首个眩晕魂技释放应成功");
        assert_eq!(first.event.sequence, 1);
        assert_eq!(first.event.beast_damage, 0);
        assert_eq!(first.event.player_hp_after, first.event.player_hp_before);
        assert!(
            first
                .skill
                .as_ref()
                .expect("应有首个眩晕魂技回执")
                .effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-stun-test")
        );
        assert!(
            first
                .battle
                .active_effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-stun-test")
        );

        store
            .rollback_content_revision(baseline.id)
            .expect("眩晕战斗中回滚内容 revision 应成功");
        assert_eq!(
            store
                .active_content_revision()
                .expect("应读取眩晕回滚后的 active revision")
                .id,
            baseline.id
        );

        drop(store);
        let restored = Store::initialize(directory.path(), &DatabaseConfig::default())
            .expect("眩晕战斗快照应可热重载");
        let second = restored
            .attack_battle_with_operation(
                &identity(),
                &transfer_operation("攻击", "stun-v1-second"),
            )
            .expect("回滚后第二序列应仍跳过魂兽反击");
        assert_eq!(second.event.sequence, 2);
        assert_eq!(second.event.beast_damage, 0);
        assert!(
            second
                .expired_effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-stun-test")
        );
        assert!(
            !second
                .battle
                .active_effects
                .iter()
                .any(|effect| effect.effect_key == "entangle-stun-test")
        );

        let third = restored
            .attack_battle_with_operation(&identity(), &transfer_operation("攻击", "stun-v1-third"))
            .expect("眩晕到期后普通攻击应继续受到反击");
        assert_eq!(third.event.sequence, 3);
        assert!(third.event.beast_damage > 0);
    }

