    #[test]
    fn v24_content_metadata_pages_are_stable_and_bounded() {
        let (_directory, store) = test_store();

        let draft = content_effect_package("page-draft", "page-draft-effect", "entangle");
        store
            .stage_content_package(&draft)
            .expect("应写入待校验草稿");

        let rejected = content_effect_package(
            "page-rejected",
            "page-rejected-effect",
            "missing-page-skill",
        );
        store
            .stage_content_package(&rejected)
            .expect("应写入将被拒绝的草稿");
        assert!(
            !store
                .validate_content_draft("page-rejected", 1)
                .expect("应校验将被拒绝的草稿")
                .errors
                .is_empty()
        );

        let validated =
            content_effect_package("page-validated", "page-validated-effect", "entangle");
        store
            .stage_content_package(&validated)
            .expect("应写入待发布草稿");
        assert!(
            store
                .validate_content_draft("page-validated", 1)
                .expect("应校验待发布草稿")
                .errors
                .is_empty()
        );

        for (package_key, effect_key) in [
            ("page-published-one", "page-published-effect-one"),
            ("page-published-two", "page-published-effect-two"),
            ("page-published-three", "page-published-effect-three"),
        ] {
            let package = content_effect_package(package_key, effect_key, "entangle");
            store
                .stage_content_package(&package)
                .expect("应写入待发布内容包");
            assert!(
                store
                    .validate_content_draft(package_key, 1)
                    .expect("应校验待发布内容包")
                    .errors
                    .is_empty()
            );
            store
                .publish_content_draft(package_key, 1)
                .expect("应发布内容包");
        }

        let first_drafts = store
            .list_content_drafts(None, 2)
            .expect("应读取首个草稿分页");
        assert_eq!(first_drafts.entries.len(), 2);
        assert_eq!(first_drafts.entries[0].status, "draft");
        assert_eq!(first_drafts.entries[1].status, "rejected");
        assert!(
            first_drafts.entries[1]
                .validation_json
                .contains("missing-page-skill")
        );
        assert_eq!(first_drafts.next_after_id, Some(first_drafts.entries[1].id));
        let remaining_drafts = store
            .list_content_drafts(first_drafts.next_after_id, 100)
            .expect("应读取剩余草稿分页");
        assert_eq!(remaining_drafts.entries.len(), 4);
        assert_eq!(remaining_drafts.entries[0].status, "validated");
        assert_eq!(
            remaining_drafts
                .entries
                .iter()
                .filter(|entry| entry.status == "published")
                .count(),
            3
        );
        assert!(remaining_drafts.next_after_id.is_none());
        assert!(
            remaining_drafts
                .entries
                .windows(2)
                .all(|entries| entries[0].id < entries[1].id)
        );

        let first_revisions = store
            .list_content_revisions(None, 2)
            .expect("应读取首个 revision 分页");
        assert_eq!(first_revisions.entries.len(), 2);
        assert!(
            first_revisions
                .entries
                .iter()
                .all(|entry| entry.member_count > 0)
        );
        assert_eq!(
            first_revisions.next_after_id,
            Some(first_revisions.entries[1].revision.id)
        );
        let remaining_revisions = store
            .list_content_revisions(first_revisions.next_after_id, 100)
            .expect("应读取剩余 revision 分页");
        assert_eq!(remaining_revisions.entries.len(), 2);
        assert!(remaining_revisions.next_after_id.is_none());
        assert!(
            remaining_revisions
                .entries
                .windows(2)
                .all(|entries| entries[0].revision.id < entries[1].revision.id)
        );

        let first_activations = store
            .list_content_activations(None, 2)
            .expect("应读取首个 activation 分页");
        assert_eq!(first_activations.entries.len(), 2);
        assert_eq!(first_activations.entries[0].reason, "initial");
        assert_eq!(first_activations.entries[1].reason, "publish");
        assert_eq!(
            first_activations.next_after_id,
            Some(first_activations.entries[1].id)
        );
        let remaining_activations = store
            .list_content_activations(first_activations.next_after_id, 100)
            .expect("应读取剩余 activation 分页");
        assert_eq!(remaining_activations.entries.len(), 2);
        assert!(remaining_activations.next_after_id.is_none());
        assert!(
            remaining_activations
                .entries
                .windows(2)
                .all(|entries| entries[0].id < entries[1].id)
        );

        assert!(
            store.list_content_drafts(Some(-1), 1).is_err(),
            "负数游标必须被拒绝"
        );
        assert!(
            store.list_content_revisions(None, 0).is_err(),
            "零分页大小必须被拒绝"
        );
        assert!(
            store.list_content_activations(None, 101).is_err(),
            "超过上限的分页大小必须被拒绝"
        );
    }

    #[test]
    fn v23_full_catalog_package_is_visible_only_in_its_active_revision() {
        let (_directory, store) = test_store();
        let baseline = store
            .active_content_revision()
            .expect("baseline content revision should exist");
        let package = ContentPackage {
            package_key: "test-full-catalog".to_string(),
            revision: 1,
            author: "test".to_string(),
            minimum_runtime: String::new(),
            wuhun: vec![WuhunPackageEntry {
                name: "test catalog wuhun".to_string(),
                category: "控制系".to_string(),
                form: "test form".to_string(),
                description: "test catalog wuhun".to_string(),
                weight: 100_000,
                stats: WuhunStatsPackageEntry {
                    attack_percent: 125,
                    defense_percent: 110,
                    strength_percent: 100,
                    agility_percent: 100,
                    spirit_percent: 100,
                    endurance_percent: 100,
                    perception_percent: 100,
                    luck_percent: 100,
                },
            }],
            skills: vec![SkillPackageEntry {
                skill_key: "test-catalog-skill".to_string(),
                name: "test catalog skill".to_string(),
                skill_type: "active".to_string(),
                wuhun_category: "控制系".to_string(),
                ring_index: 1,
                soul_power_cost: 10,
                cooldown_rounds: 1,
                base_damage: 20,
                spirit_ratio_percent: 100,
                strength_ratio_percent: 0,
                description: "test catalog skill".to_string(),
                enabled: true,
                starter: true,
            }],
            effects: vec![EffectPackageEntry {
                effect_key: "test-catalog-effect".to_string(),
                skill_key: "test-catalog-skill".to_string(),
                trigger_kind: "on_release".to_string(),
                target_kind: "beast".to_string(),
                operation: "modify_stat".to_string(),
                attribute_key: "beast_attack".to_string(),
                value_mode: "percent_delta".to_string(),
                value: -25,
                duration_rounds: 2,
                chance_percent: 100,
                stack_policy: "strongest".to_string(),
                parameters: Default::default(),
                description: "test catalog effect".to_string(),
                enabled: true,
            }],
            soul_beasts: vec![SoulBeastPackageEntry {
                beast_key: "test-catalog-beast".to_string(),
                name: "test catalog beast".to_string(),
                description: "test catalog beast".to_string(),
                map_key: "sunset-forest".to_string(),
                age: 20,
                level_required: 1,
                max_hp: 100,
                attack: 20,
                defense: 5,
                speed: 5,
                exp_reward: 10,
                drop_item_key: "small-healing-potion".to_string(),
                drop_quantity: 1,
                enabled: true,
            }],
            soul_rings: vec![SoulRingPackageEntry {
                ring_key: "test-catalog-ring".to_string(),
                name: "test catalog ring".to_string(),
                soul_beast_key: "test-catalog-beast".to_string(),
                skill_key: "test-catalog-skill".to_string(),
                ring_index: 1,
                age: 20,
                color: "white".to_string(),
                description: "test catalog ring".to_string(),
                enabled: true,
            }],
            transitions: Vec::new(),
        };
        let loaded = LoadedContentPackage {
            content_hash: content_hash(&package).expect("content hash"),
            package,
            source_format: "json".to_string(),
        };
        store
            .stage_content_package(&loaded)
            .expect("full catalog package should stage");
        let validation = store
            .validate_content_draft("test-full-catalog", 1)
            .expect("full catalog package should validate");
        assert!(validation.errors.is_empty(), "{validation:?}");
        store
            .publish_content_draft("test-full-catalog", 1)
            .expect("full catalog package should publish");

        let connection = store.open().expect("active catalog should open");
        for (kind, key) in [
            ("wuhun", "test catalog wuhun"),
            ("skill", "test-catalog-skill"),
            ("starter-skill", "test-catalog-skill"),
            ("effect", "test-catalog-effect"),
            ("beast", "test-catalog-beast"),
            ("ring", "test-catalog-ring"),
        ] {
            assert!(active_content_member_exists(&connection, kind, key).unwrap());
        }
        let total_weight = connection
            .query_row(
                r#"
                SELECT SUM(wuhun.weight)
                  FROM wuhun
                  JOIN content_revision_member member
                    ON member.member_kind = 'wuhun' AND member.member_key = wuhun.name
                 WHERE member.revision_id = (
                           SELECT revision_id
                             FROM content_revision_activation
                            ORDER BY id DESC
                            LIMIT 1
                       )
                "#,
                [],
                |row| row.get::<_, i64>(0),
            )
            .expect("active wuhun weight should exist");
        assert_eq!(
            load_wuhun_at_weight_ticket(&connection, total_weight - 1, total_weight)
                .unwrap()
                .expect("weighted catalog should contain the custom wuhun")
                .1
                .name,
            "test catalog wuhun"
        );
        let wuhun_id = connection
            .query_row(
                "SELECT id FROM wuhun WHERE name = 'test catalog wuhun'",
                [],
                |row| row.get::<_, i64>(0),
            )
            .expect("custom wuhun should exist");
        assert_eq!(
            load_wuhun_combat_modifier(&connection, wuhun_id, "控制系")
                .expect("active custom wuhun should have a template")
                .attack_percent,
            125
        );
        assert_eq!(
            load_skill_effects(&connection, "test-catalog-skill")
                .expect("active custom effects should load")
                .len(),
            1
        );
        assert!(
            query_soul_beasts(&connection, Some("sunset-forest"), Some(1), 20, 0)
                .expect("active custom beasts should load")
                .iter()
                .any(|beast| beast.beast_key == "test-catalog-beast")
        );
        drop(connection);

        store
            .rollback_content_revision(baseline.id)
            .expect("catalog rollback should succeed");
        let connection = store.open().expect("rolled-back catalog should open");
        assert!(!active_content_member_exists(&connection, "wuhun", "test catalog wuhun").unwrap());
        assert!(load_wuhun_combat_modifier(&connection, wuhun_id, "控制系").is_err());
        assert!(
            load_skill_effects(&connection, "test-catalog-skill")
                .expect("inactive custom effects should resolve as empty")
                .is_empty()
        );
        assert!(
            !query_soul_beasts(&connection, Some("sunset-forest"), Some(1), 20, 0)
                .expect("rolled-back custom beasts should load as absent")
                .iter()
                .any(|beast| beast.beast_key == "test-catalog-beast")
        );
    }

    #[test]
    fn recorded_v22_with_damaged_schema_or_cross_table_trigger_fails_closed() {
        for mutation in [
            "DROP TABLE battle_effect_expiration;",
            "DROP INDEX effect_definition_skill_page;",
            "DROP TRIGGER battle_skill_event_effect_v2_snapshot;",
            "DROP TRIGGER wuhun_stat_template_scope_guard;",
        ] {
            assert_v22_damage_fails_closed(mutation);
        }
        assert_v22_damage_fails_closed(
            r#"
            CREATE TRIGGER player_wuhun_reads_effect_definition
            AFTER INSERT ON player_wuhun
            BEGIN
                SELECT EXISTS(SELECT 1 FROM effect_definition);
            END;
            "#,
        );
    }

