    #[test]
    fn player_alias_crud_is_scoped_audited_and_conflict_safe() {
        let (_directory, store) = test_store();
        let owner = identity();
        let other = recipient_identity();
        let create = transfer_operation("设置快捷键", "alias-create");
        assert!(
            store
                .set_player_alias_with_operation(&owner, "状态", "查", &create)
                .is_err()
        );

        store
            .register_player(&owner, "快捷键玩家", "男")
            .expect("应创建快捷键测试角色");
        store
            .register_player(&other, "隔离玩家", "女")
            .expect("应创建隔离测试角色");

        let created = store
            .set_player_alias_with_operation(&owner, "状态", "查", &create)
            .expect("应创建快捷键");
        assert!(created.created);
        assert_eq!(created.alias.target_command, "状态");
        assert_eq!(created.alias.alias, "查");

        let replay = store
            .set_player_alias_with_operation(&owner, "状态", "查", &create)
            .expect_err("相同消息 ID 不能重复写入快捷键");
        assert!(replay.contains("已经处理"));

        let repeated = store
            .set_player_alias_with_operation(
                &owner,
                "状态",
                "查",
                &transfer_operation("设置快捷键", "alias-repeat"),
            )
            .expect("相同映射可幂等确认");
        assert!(!repeated.created);
        assert_eq!(repeated.alias.id, created.alias.id);

        let conflict = store
            .set_player_alias_with_operation(
                &owner,
                "背包",
                "查",
                &transfer_operation("设置快捷键", "alias-conflict"),
            )
            .expect_err("不同原指令不能覆盖已占用快捷键");
        assert!(conflict.contains("已绑定"));

        let aliases = store.list_player_aliases(&owner).expect("应读取快捷键列表");
        assert_eq!(aliases, vec![created.alias.clone()]);
        assert_eq!(
            store
                .resolve_player_alias(&owner, "查")
                .expect("应按稳定身份解析快捷键"),
            Some(created.alias.clone())
        );
        assert_eq!(
            store
                .resolve_player_alias(&other, "查")
                .expect("其他玩家读取不应失败"),
            None
        );

        let wrong_target = store
            .delete_player_alias_with_operation(
                &owner,
                "背包",
                "查",
                &transfer_operation("删除快捷键", "alias-wrong-target"),
            )
            .expect_err("删除时必须核对原指令");
        assert!(wrong_target.contains("不属于原指令"));
        assert!(
            store
                .delete_player_alias_with_operation(
                    &owner,
                    "状态",
                    "不存在",
                    &transfer_operation("删除快捷键", "alias-missing"),
                )
                .is_err()
        );

        let deleted = store
            .delete_player_alias_with_operation(
                &owner,
                "状态",
                "查",
                &transfer_operation("删除快捷键", "alias-delete"),
            )
            .expect("应删除快捷键");
        assert_eq!(deleted, created.alias);
        assert!(
            store
                .list_player_aliases(&owner)
                .expect("删除后仍应读取列表")
                .is_empty()
        );

        let operations = store
            .list_operation_logs(&owner, None, 100)
            .expect("应读取快捷键操作审计");
        let commands = operations
            .entries
            .iter()
            .map(|entry| entry.command.as_str())
            .collect::<Vec<_>>();
        assert_eq!(commands, vec!["设置快捷键", "设置快捷键", "删除快捷键"]);
    }

    #[test]
    fn v30_content_admin_audit_is_atomic_and_replay_safe() {
        let (directory, store) = test_store();
        let actor = ContentAdminAuditActor {
            role: "content_admin",
            session_fingerprint: "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
        };
        let valid = content_effect_package("v30-valid", "v30-valid-effect", "entangle");
        store
            .stage_content_package(&valid)
            .expect("应写入 v30 可发布草稿");
        assert!(
            store
                .validate_content_draft_as_admin("v30-valid", 1, actor)
                .expect("管理员应校验 v30 草稿")
                .errors
                .is_empty()
        );
        let published = store
            .publish_content_draft_as_admin("v30-valid", 1, actor)
            .expect("管理员应发布 v30 草稿");
        assert!(!published.replayed);
        assert!(
            store
                .publish_content_draft_as_admin("v30-valid", 1, actor)
                .expect("管理员重复发布应重放")
                .replayed
        );

        let rejected =
            content_effect_package("v30-rejected", "v30-rejected-effect", "missing-v30-skill");
        store
            .stage_content_package(&rejected)
            .expect("应写入 v30 被拒绝草稿");
        assert!(
            !store
                .validate_content_draft_as_admin("v30-rejected", 1, actor)
                .expect("管理员应返回 v30 拒绝报告")
                .errors
                .is_empty()
        );

        let operations = store
            .list_content_admin_operations(None, 100)
            .expect("应读取 v30 管理员审计");
        assert_eq!(operations.entries.len(), 4);
        assert_eq!(
            operations
                .entries
                .iter()
                .map(|entry| (entry.action.as_str(), entry.outcome.as_str()))
                .collect::<Vec<_>>(),
            vec![
                ("validate", "validated"),
                ("publish", "published"),
                ("publish", "replayed"),
                ("validate", "rejected"),
            ]
        );
        assert!(
            operations
                .entries
                .iter()
                .all(|entry| entry.actor_fingerprint == actor.session_fingerprint)
        );
        assert_eq!(
            operations.entries[1].revision_id,
            Some(published.revision.id)
        );
        assert_eq!(
            operations.entries[2].revision_id,
            Some(published.revision.id)
        );
        assert!(operations.entries[3].revision_id.is_none());

        let restaged = content_effect_package("v30-rejected", "v30-restaged-effect", "entangle");
        let restaged_draft = store
            .stage_content_package(&restaged)
            .expect("被拒绝草稿应允许以相同身份重新暂存");
        assert_eq!(restaged_draft.status, "draft");
        drop(store);
        let store = Store::initialize(directory.path(), &DatabaseConfig::default())
            .expect("重暂存后历史管理员审计不应阻断启动");

        let invalid_actor = ContentAdminAuditActor {
            role: "owner",
            session_fingerprint: actor.session_fingerprint,
        };
        assert!(
            store
                .validate_content_draft_as_admin("v30-valid", 1, invalid_actor)
                .is_err()
        );
        assert_eq!(
            store
                .list_content_admin_operations(None, 100)
                .expect("非法角色后审计应保持不变")
                .entries
                .len(),
            4
        );

        let atomic = content_effect_package("v30-atomic", "v30-atomic-effect", "entangle");
        store
            .stage_content_package(&atomic)
            .expect("应写入 v30 原子性草稿");
        let connection = store.open().expect("应打开 v30 原子性数据库");
        connection
            .execute_batch(
                r#"
                CREATE TRIGGER content_admin_operation_test_failure
                BEFORE INSERT ON content_admin_operation
                BEGIN
                    SELECT RAISE(ABORT, 'test audit failure');
                END;
                "#,
            )
            .expect("应构造审计写入失败");
        drop(connection);
        assert!(
            store
                .validate_content_draft_as_admin("v30-atomic", 1, actor)
                .is_err()
        );
        let atomic_draft = store
            .list_content_drafts(None, 100)
            .expect("应读取原子性草稿")
            .entries
            .into_iter()
            .find(|entry| entry.package_key == "v30-atomic")
            .expect("应保留 v30 原子性草稿");
        assert_eq!(atomic_draft.status, "draft");
        assert_eq!(
            store
                .list_content_admin_operations(None, 100)
                .expect("审计失败后不应追加记录")
                .entries
                .len(),
            4
        );
    }

    #[test]
    fn v31_content_admin_rollback_is_atomic_and_append_only() {
        let (_directory, store) = test_store();
        let actor = ContentAdminAuditActor {
            role: "content_admin",
            session_fingerprint: "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
        };
        let baseline = store
            .active_content_revision()
            .expect("应读取 v31 回滚基线 revision");
        let target = content_effect_package("v31-target", "v31-target-effect", "entangle");
        store
            .stage_content_package(&target)
            .expect("应写入 v31 回滚目标草稿");
        assert!(
            store
                .validate_content_draft("v31-target", 1)
                .expect("应校验 v31 回滚目标草稿")
                .errors
                .is_empty()
        );
        let published = store
            .publish_content_draft("v31-target", 1)
            .expect("应发布 v31 回滚目标 revision");

        let rollback = store
            .rollback_content_revision_as_admin(baseline.id, actor)
            .expect("管理员应回滚到 v31 基线 revision");
        assert_eq!(rollback.revision, baseline);
        assert_eq!(
            store
                .active_content_revision()
                .expect("应读取回滚后的 active revision")
                .id,
            baseline.id
        );

        let repeated = store
            .rollback_content_revision_as_admin(baseline.id, actor)
            .expect("显式重复回滚仍应追加 activation");
        assert_ne!(repeated.activation_id, rollback.activation_id);
        let audits = store
            .list_content_admin_rollback_operations(None, 100)
            .expect("应读取 v31 管理员回滚审计");
        assert_eq!(audits.entries.len(), 2);
        assert!(audits.entries.iter().all(|entry| {
            entry.actor_role == "content_admin"
                && entry.actor_fingerprint == actor.session_fingerprint
                && entry.revision_id == baseline.id
        }));
        assert_eq!(audits.entries[0].activation_id, rollback.activation_id);
        assert_eq!(audits.entries[1].activation_id, repeated.activation_id);

        let invalid_actor = ContentAdminAuditActor {
            role: "owner",
            session_fingerprint: actor.session_fingerprint,
        };
        assert!(
            store
                .rollback_content_revision_as_admin(published.revision.id, invalid_actor)
                .is_err()
        );
        assert_eq!(
            store
                .list_content_admin_rollback_operations(None, 100)
                .expect("非法角色后审计应保持不变")
                .entries
                .len(),
            2
        );

        let atomic = content_effect_package("v31-atomic", "v31-atomic-effect", "entangle");
        store
            .stage_content_package(&atomic)
            .expect("应写入 v31 原子性草稿");
        assert!(
            store
                .validate_content_draft("v31-atomic", 1)
                .expect("应校验 v31 原子性草稿")
                .errors
                .is_empty()
        );
        let active_before_failure = store
            .publish_content_draft("v31-atomic", 1)
            .expect("应发布 v31 原子性 revision")
            .revision;
        let connection = store.open().expect("应打开 v31 原子性数据库");
        let activation_count_before_failure = connection
            .query_row(
                "SELECT COUNT(*) FROM content_revision_activation",
                [],
                |row| row.get::<_, i64>(0),
            )
            .expect("应统计回滚前 activation");
        connection
            .execute_batch(
                r#"
                CREATE TRIGGER content_admin_rollback_operation_test_failure
                BEFORE INSERT ON content_admin_rollback_operation
                BEGIN
                    SELECT RAISE(ABORT, 'test rollback audit failure');
                END;
                "#,
            )
            .expect("应构造回滚审计写入失败");
        drop(connection);

        assert!(
            store
                .rollback_content_revision_as_admin(baseline.id, actor)
                .is_err()
        );
        assert_eq!(
            store
                .active_content_revision()
                .expect("审计失败后应保留原 active revision"),
            active_before_failure
        );
        let connection = store.open().expect("应读取 v31 原子性数据库");
        let activation_count_after_failure = connection
            .query_row(
                "SELECT COUNT(*) FROM content_revision_activation",
                [],
                |row| row.get::<_, i64>(0),
            )
            .expect("应统计回滚失败后的 activation");
        assert_eq!(
            activation_count_after_failure,
            activation_count_before_failure
        );
        assert_eq!(
            store
                .list_content_admin_rollback_operations(None, 100)
                .expect("审计失败后不应追加回滚记录")
                .entries
                .len(),
            2
        );
    }

    #[test]
    fn v32_content_admin_draft_stage_audit_is_atomic_and_replay_safe() {
        let (directory, store) = test_store();
        let actor = ContentAdminAuditActor {
            role: "content_admin",
            session_fingerprint: "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
        };
        let package = content_effect_package("v32-stage", "v32-stage-effect", "entangle");
        let staged = store
            .stage_content_package_as_admin(&package, actor)
            .expect("管理员应暂存 v32 内容包");
        assert!(!staged.replayed);
        assert_eq!(staged.draft.status, "draft");

        let restaged = store
            .stage_content_package_as_admin(&package, actor)
            .expect("未发布草稿应允许管理员重新暂存");
        assert!(!restaged.replayed);
        assert_eq!(restaged.draft.id, staged.draft.id);
        let operations = store
            .list_content_admin_draft_stage_operations(None, 100)
            .expect("应读取 v32 管理员暂存审计");
        assert_eq!(operations.entries.len(), 2);
        assert!(operations.entries.iter().all(|entry| {
            entry.actor_role == "content_admin"
                && entry.actor_fingerprint == actor.session_fingerprint
                && entry.package_key == "v32-stage"
                && entry.outcome == "staged"
        }));

        let restaged_package =
            content_effect_package("v32-stage", "v32-restaged-effect", "entangle");
        let restaged = store
            .stage_content_package_as_admin(&restaged_package, actor)
            .expect("未发布草稿应允许以新内容重新暂存");
        assert_ne!(restaged.draft.content_hash, staged.draft.content_hash);
        drop(store);
        let store = Store::initialize(directory.path(), &DatabaseConfig::default())
            .expect("重暂存后历史暂存审计不应阻断启动");
        assert_eq!(
            store
                .list_content_admin_draft_stage_operations(None, 100)
                .expect("应读取重启后的暂存审计")
                .entries
                .len(),
            3
        );

        assert!(
            store
                .validate_content_draft("v32-stage", 1)
                .expect("应校验 v32 暂存草稿")
                .errors
                .is_empty()
        );
        store
            .publish_content_draft("v32-stage", 1)
            .expect("应发布 v32 暂存草稿");
        let replayed = store
            .stage_content_package_as_admin(&restaged_package, actor)
            .expect("已发布同哈希草稿应幂等暂存");
        assert!(replayed.replayed);
        assert_eq!(replayed.draft.status, "published");
        let operations = store
            .list_content_admin_draft_stage_operations(None, 100)
            .expect("应读取已发布草稿暂存审计");
        assert_eq!(operations.entries.len(), 4);
        assert_eq!(operations.entries[3].outcome, "replayed");

        let invalid_actor = ContentAdminAuditActor {
            role: "owner",
            session_fingerprint: actor.session_fingerprint,
        };
        assert!(
            store
                .stage_content_package_as_admin(&restaged_package, invalid_actor)
                .is_err()
        );
        assert_eq!(
            store
                .list_content_admin_draft_stage_operations(None, 100)
                .expect("非法角色后审计应保持不变")
                .entries
                .len(),
            4
        );

        let atomic = content_effect_package("v32-atomic", "v32-atomic-effect", "entangle");
        let connection = store.open().expect("应打开 v32 原子性数据库");
        connection
            .execute_batch(
                r#"
                CREATE TRIGGER content_admin_draft_stage_operation_test_failure
                BEFORE INSERT ON content_admin_draft_stage_operation
                BEGIN
                    SELECT RAISE(ABORT, 'test stage audit failure');
                END;
                "#,
            )
            .expect("应构造暂存审计写入失败");
        drop(connection);
        assert!(
            store
                .stage_content_package_as_admin(&atomic, actor)
                .is_err()
        );
        assert!(
            !store
                .list_content_drafts(None, 100)
                .expect("审计失败后应读取草稿列表")
                .entries
                .iter()
                .any(|entry| entry.package_key == "v32-atomic"),
            "审计失败不能留下半写入草稿"
        );
        assert_eq!(
            store
                .list_content_admin_draft_stage_operations(None, 100)
                .expect("审计失败后不应追加暂存记录")
                .entries
                .len(),
            4
        );
    }

    fn assert_v30_damage_fails_closed(mutation: &str) {
        let directory = tempdir().expect("应创建 v30 损坏测试目录");
        let store = Store::initialize(directory.path(), &DatabaseConfig::default())
            .expect("v30 迁移应成功");
        let connection = store.open().expect("应打开 v30 损坏测试数据库");
        connection
            .execute_batch(mutation)
            .expect("应能构造 v30 schema 损坏");
        drop(connection);
        drop(store);
        let error = Store::initialize(directory.path(), &DatabaseConfig::default())
            .expect_err("记录 v30 后损坏 schema 必须拒绝启动");
        assert!(
            error.contains("v30") || error.contains("content_admin_operation"),
            "v30 损坏未由对应校验拒绝：{mutation}；实际错误：{error}"
        );
    }

    #[test]
    fn recorded_v30_with_damaged_schema_or_trigger_fails_closed() {
        for mutation in [
            "DROP TABLE content_admin_operation;",
            "DROP INDEX content_admin_operation_draft_page;",
            "DROP TRIGGER content_admin_operation_state_guard;",
        ] {
            assert_v30_damage_fails_closed(mutation);
        }
        assert_v30_damage_fails_closed(
            r#"
            CREATE TRIGGER content_admin_operation_shadow
            AFTER INSERT ON content_admin_operation
            BEGIN SELECT 1; END;
            "#,
        );
    }

